import { useRef } from 'react'
import {
  getOwnerUserList,
  updateOwnerUserStatus,
  PlatformUserTypes
} from '@/apis/admin/platform-user'
import ExcelTable from '@/components/exportExcel'
import { ActionType, ProFormInstance, ProColumns } from '@ant-design/pro-components'
import { Button, message, Tag, Tooltip, Popconfirm, Space } from 'antd'
import { StopOutlined, CheckCircleOutlined } from '@ant-design/icons'
import { ResultEnum } from '@/utils/enums/httpEnum'
import dayjs from 'dayjs'

// 用户状态映射
const userStatusMap: Record<number, { text: string; color: string }> = {
  1: { text: '启用', color: 'success' },
  2: { text: '禁用', color: 'error' }
}

// 格式化时间
const formatTime = (time: string) => {
  if (!time) {
    return '-'
  }
  return dayjs(time).format('YYYY-MM-DD HH:mm:ss')
}

const UserList: React.FC = () => {
  const actionRef = useRef<ActionType>()
  const formRef = useRef<ProFormInstance>()

  // 导出用户列表
  const handleExport = () => {
    message.info('导出功能开发中')
  }

  // 禁用/启用用户
  const handleToggleStatus = async (record: PlatformUserTypes.AiPostOwnerUserListDto) => {
    try {
      const newStatus = record.status === 1 ? 2 : 1
      const res = await updateOwnerUserStatus(record.id, {
        userId: record.id,
        status: newStatus
      })

      if (res.code === ResultEnum.SUCCESS) {
        message.success(`${record.status === 1 ? '禁用' : '启用'}成功`)
        actionRef.current?.reload()
      } else {
        message.error(res.message || '操作失败')
      }
    } catch (e) {
      message.error('操作失败')
    }
  }

  // 渲染订阅报纸标签
  const renderNewspapers = (papers: string[]) => {
    if (!papers || papers.length === 0) {
      return <span style={{ color: '#999' }}>-</span>
    }
    if (papers.length <= 2) {
      return (
        <Space size="small">
          {papers.map((p, idx) => (
            <Tag key={idx} color="blue">
              {p}
            </Tag>
          ))}
        </Space>
      )
    }
    return (
      <Space size="small">
        <Tag color="blue">{papers[0]}</Tag>
        <Tag color="blue">{papers[1]}</Tag>
        <span style={{ fontSize: 12, color: '#64748B' }}>等{papers.length}种</span>
      </Space>
    )
  }

  // 格式化地址码
  const formatAddressCode = (code: string) => {
    if (!code) {
      return <span style={{ color: '#999' }}>-</span>
    }
    const formatted = `${code.slice(0, 6)}-${code.slice(6, 10)}-${code.slice(10, 12)}-${code.slice(
      12
    )}`
    return (
      <Tooltip title={code}>
        <span style={{ fontFamily: 'Courier New, monospace', fontSize: 13 }}>{formatted}</span>
      </Tooltip>
    )
  }

  // 表格列定义
  const columns: ProColumns<PlatformUserTypes.AiPostOwnerUserListDto>[] = [
    {
      title: '用户ID',
      dataIndex: 'id',
      key: 'id',
      width: 100,
      hideInSearch: true,
      render: text => (
        <span style={{ fontFamily: 'Courier New, monospace', fontWeight: 500 }}>{text}</span>
      )
    },
    {
      title: '手机号',
      dataIndex: 'phone',
      key: 'phone',
      width: 140
    },
    {
      title: '昵称',
      dataIndex: 'nickname',
      key: 'nickname',
      width: 140
    },
    {
      title: '订阅报纸',
      dataIndex: 'paperData',
      key: 'paperData',
      width: 180,
      hideInSearch: true,
      render: text => renderNewspapers(text as string[])
    },
    {
      title: '地址码',
      dataIndex: 'houseNo',
      key: 'houseNo',
      width: 160,
      hideInSearch: true,
      render: text => formatAddressCode(text as string)
    },
    {
      title: '户号',
      dataIndex: 'houseNo',
      key: 'houseNumber',
      width: 120,
      hideInSearch: true,
      render: text => {
        if (!text) {
          return <span style={{ color: '#999' }}>-</span>
        }
        return <span style={{ fontFamily: 'Courier New, monospace' }}>{text}</span>
      }
    },
    {
      title: '积分余额',
      dataIndex: 'pointsBalance',
      key: 'pointsBalance',
      width: 120,
      hideInSearch: true,
      render: text => (
        <span style={{ fontFamily: 'Courier New, monospace', fontWeight: 500 }}>
          {Number(text || 0).toLocaleString()}
        </span>
      )
    },
    {
      title: '即将过期积分',
      dataIndex: 'pointsExpiring',
      key: 'pointsExpiring',
      width: 120,
      hideInSearch: true,
      render: text => {
        const points = Number(text || 0)
        return (
          <span
            style={{
              fontFamily: 'Courier New, monospace',
              color: points > 0 ? '#F59E0B' : '#64748B'
            }}
          >
            {points}
          </span>
        )
      }
    },
    {
      title: '注册时间',
      dataIndex: 'createdAt',
      key: 'createdAt',
      width: 170,
      hideInSearch: true,
      render: text => (
        <span style={{ fontSize: 13, whiteSpace: 'nowrap' }}>{formatTime(text as string)}</span>
      )
    },
    {
      title: '最后活跃',
      dataIndex: 'lastActiveTime',
      key: 'lastActiveTime',
      width: 170,
      hideInSearch: true,
      render: text => (
        <span style={{ fontSize: 13, whiteSpace: 'nowrap' }}>{formatTime(text as string)}</span>
      )
    },
    {
      title: '状态',
      dataIndex: 'status',
      key: 'status',
      width: 100,
      valueType: 'select',
      valueEnum: {
        1: { text: '启用', status: 'Success' },
        2: { text: '禁用', status: 'Error' }
      },
      render: (_, record) => {
        const status = userStatusMap[record.status]
        return <Tag color={status?.color || 'default'}>{status?.text || '未知'}</Tag>
      }
    },
    {
      title: '操作',
      key: 'option',
      valueType: 'option',
      fixed: 'right',
      width: 80,
      render: (_, record) => [
        record.status === 1 ? (
          <Tooltip title="禁用" key={`${record.id}-disable`}>
            <Popconfirm title="确定要禁用该用户吗？" onConfirm={() => handleToggleStatus(record)}>
              <Button type="link" danger title="禁用" icon={<StopOutlined />} />
            </Popconfirm>
          </Tooltip>
        ) : (
          <Tooltip title="启用" key={`${record.id}-enable`}>
            <Button
              key={`${record.id}-enable`}
              type="link"
              title="启用"
              icon={<CheckCircleOutlined />}
              style={{ color: '#52c41a' }}
              onClick={() => handleToggleStatus(record)}
            />
          </Tooltip>
        )
      ]
    }
  ]

  return (
    <ExcelTable
      key="user-list"
      formRef={formRef}
      columns={columns}
      requestFn={async params => {
        const { page, pageSize, nickname, phone, status, ...rest } = params
        return await getOwnerUserList({
          page,
          pageSize,
          nickname,
          phone,
          status,
          ...rest
        })
      }}
      actionRef={actionRef}
      rowSelection={false}
      options={{
        fullScreen: false,
        reload: true,
        setting: false,
        density: false
      }}
      search={{
        span: 6,
        labelWidth: 'auto'
      }}
      toolBarRenderFn={() => []}
      scroll={{ x: 1400 }}
    />
  )
}

export default UserList
